1	import { BadRequestException, ForbiddenException, Injectable, NotFoundException } from '@nestjs/common';
2	import { SupabaseService } from '../supabase/supabase.service';
3	import { EstoqueService } from '../estoque/estoque.service';
4	import { CombosService, ItemExpandido } from '../combos/combos.service';
5	
6	export interface AbrirComandaBody {
7	  mesa_id?: number;
8	  cliente_nome: string;
9	  cliente_telefone: string;
10	}
11	
12	export interface ItemComandaBody {
13	  product_id?: number;
14	  combo_id?: number;
15	  quantity: number;
16	  observacao?: string;
17	}
18	
19	@Injectable()
20	export class SalaoService {
21	  constructor(
22	    private supabase: SupabaseService,
23	    private estoque: EstoqueService,
24	    private combosService: CombosService,
25	  ) {}
26	
27	  async mesas(restaurantId: number) {
28	    const { data: mesas, error } = await this.supabase.client
29	      .from('mesas')
30	      .select('id, numero, nome, status')
31	      .eq('restaurant_id', restaurantId)
32	      .order('numero', { ascending: true });
33	    if (error) throw error;
34	
35	    // Precisa saber de quem é a comanda em cada mesa ocupada — o garçom só pode
36	    // clicar/entrar se a comanda for dele (ver garcom-portal, grid de mesas).
37	    const { data: comandas } = await this.supabase.client
38	      .from('orders')
39	      .select('id, mesa_id, garcom_id, cliente_mesa_nome, total, garcons(nome), aberto_por_nome, conferencia_solicitada_em')
40	      .eq('restaurant_id', restaurantId)
41	      .eq('canal', 'presencial')
42	      .in('status', ['aberta', 'fechada_garcom'])
43	      .not('mesa_id', 'is', null);
44	
45	    const comandaPorMesa = new Map((comandas ?? []).map((c: any) => [c.mesa_id, c]));
46	
47	    return (mesas ?? []).map((m: any) => ({ ...m, comanda: comandaPorMesa.get(m.id) ?? null }));
48	  }
49	
50	  // Acompanhamento público via QR (ideia 13) — sem auth, só o essencial pro cliente da mesa.
51	  async acompanharPorToken(token: string) {
52	    const { data: comanda } = await this.supabase.client
53	      .from('orders')
54	      .select('id, restaurant_id, status, numero_comanda, desconto_valor, acrescimo_valor, gorjeta_valor, conferencia_solicitada_em, mesas(numero, nome), restaurants(name, gorjeta_percentual)')
55	      .eq('tracking_token', token)
56	      .eq('canal', 'presencial')
57	      .maybeSingle();
58	    if (!comanda) throw new NotFoundException('Comanda não encontrada');
59	
60	    const { data: itens } = await this.supabase.client
61	      .from('order_items')
62	      .select('id, quantity, unit_price, status, enviado_em, preparando_em, products(name)')
63	      .eq('order_id', comanda.id)
64	      .order('id', { ascending: true });
65	
66	    // Mesma fila e mesmas médias que o garçom vê — o cliente não precisa perguntar
67	    // "quantos faltam antes do meu" ou "quanto tempo em média demora".
68	    const fila = await this.filaCozinha((comanda as any).restaurant_id);
69	    const aguardandoIds = fila.itens.filter((i) => i.status === 'enviado').map((i) => i.item_id);
70	    const preparandoIds = fila.itens.filter((i) => i.status === 'preparando').map((i) => i.item_id);
71	
72	    // Conta pra conferência visual — mesmos números que o caixa usa pra fechar (ver
73	    // saldoDevedor), o cliente confere sem precisar perguntar "quanto já deu".
74	    const saldo = await this.saldoDevedor(comanda.id);
75	    const percentualGorjeta = (comanda as any).restaurants?.gorjeta_percentual ?? 0;
76	
77	    const { data: pagamentos } = await this.supabase.client
78	      .from('comanda_pagamentos')
79	      .select('valor, forma_pagamento, criado_em, taxa_cartao_valor')
80	      .eq('order_id', comanda.id)
81	      .order('criado_em', { ascending: true });
82	    const taxaCartaoTotal = (pagamentos ?? []).reduce((acc: number, p: any) => acc + (p.taxa_cartao_valor ?? 0), 0);
83	
84	    // gorjeta_valor só é gravado quando a comanda é paga (garçom/caixa escolhe o valor
85	    // na hora) — enquanto a comanda ainda está aberta o cliente não vê nenhuma gorjeta
86	    // no Total/Falta pagar, mesmo o restaurante tendo um percentual sugerido configurado.
87	    // Estimativa: calcula em cima do percentual pra já aparecer no acompanhamento antes
88	    // do pagamento; quando pago, usa o valor real cobrado (não recalcula).
89	    const gorjetaJaDefinida = (comanda as any).gorjeta_valor !== null && (comanda as any).gorjeta_valor !== undefined;
90	    const gorjetaEstimativa = !gorjetaJaDefinida && comanda.status !== 'paga' && percentualGorjeta > 0;
91	    let gorjetaValor = (comanda as any).gorjeta_valor ?? 0;
92	    let totalComGorjeta = saldo.total;
93	    let saldoComGorjeta = saldo.saldo;
94	    if (gorjetaEstimativa) {
95	      const baseCalculo = saldo.subtotal - ((comanda as any).desconto_valor ?? 0) + ((comanda as any).acrescimo_valor ?? 0);
96	      gorjetaValor = parseFloat(((baseCalculo * percentualGorjeta) / 100).toFixed(2));
