286	      if (idx >= 0) {
287	        const novo = [...prev];
288	        const novaQtd = novo[idx].qtd + delta;
289	        if (novaQtd <= 0) { novo.splice(idx, 1); return novo; }
290	        novo[idx] = { ...novo[idx], qtd: novaQtd };
291	        return novo;
292	      }
293	      if (delta < 0) return prev;
294	      return [...prev, { ...produto, price: preco, qtd: 1 }];
295	    });
