444	            </motion.div>
445	          </div>
446	        </div>
447	      </div>
448	
449	      {/* ── Stats bar ──────────────────────────────────────────────── */}
450	      <div className="bg-white border-b border-[#E4E4E7]">
451	        <div className="max-w-screen-xl mx-auto px-4 py-3 flex items-center gap-5 overflow-x-auto" style={{ scrollbarWidth: 'none' }}>
