458	          <div className="flex items-center gap-1.5 flex-shrink-0">
459	            <Icon name="Clock" size={14} className="text-[#FF7A00]" />
460	            <span className="text-sm text-[#27272A]">{ap.tempo_entrega ?? '25-40 min'}</span>
461	          </div>
