467	                <span className="text-sm text-[#27272A]">
468	                  {Number(restaurante.frete_motoboy) === 0 ? 'Frete grátis' : fmt(Number(restaurante.frete_motoboy))}
469	                </span>
470	              </div>
471	            </>
