495	              ))}
496	            </div>
497	          </div>
498	        </div>
499	      )}
500	
501	      {/* ── Banner restaurante fechado ─────────────────────────────── */}
502	      {ap.aberto === false && (
503	        <div className="bg-red-500 text-white px-4 py-3">
504	          <div className="max-w-screen-xl mx-auto flex items-center gap-2">
505	            <Icon name="Clock" size={16} />
506	            <p className="text-sm font-bold">Restaurante fechado no momento — pedidos indisponíveis</p>
507	          </div>
508	        </div>
509	      )}
510	
511	      {/* ── Carrossel de combos ativos ───────────────────────────────── */}
512	      {combos?.length > 0 && (
513	        <div className="max-w-screen-xl mx-auto px-4 pt-4">
514	          <p className="text-sm font-bold text-[#18181B] mb-3 flex items-center gap-2">
515	            <Icon name="Package" size={15} className="text-[#FF441F]" />
516	            Combos em destaque
517	          </p>
518	          <ComboCarrossel combos={combos} onAdicionar={altCarrinho} restauranteFechado={ap.aberto === false} />
519	        </div>
520	      )}
521	
522	      {/* ── Nav categorias sticky ───────────────────────────────────── */}
523	      <div className="sticky top-14 z-20 bg-white/95 backdrop-blur-md border-b border-[#E4E4E7]">
524	        <div className="max-w-screen-xl mx-auto px-4">
