532	                }`}>
533	                {tab.label}
534	              </button>
535	            ))}
536	          </div>
537	        </div>
538	      </div>
539	
540	      {/* ── Layout 2 colunas desktop ────────────────────────────────── */}
541	      <div className="max-w-screen-xl mx-auto px-4 py-6 flex gap-6 items-start pb-32 lg:pb-8">
542	
543	        {/* Produtos */}
544	        <main className="flex-1 min-w-0">
545	          {tabs.length === 0 ? (
