548	              <p className="font-medium">Cardápio em breve</p>
549	            </div>
550	          ) : produtosDaTab().length === 0 ? (
551	            <div className="text-center py-10 text-[#71717A]">
552	              <p className="text-sm">Nenhum produto nesta categoria</p>
553	            </div>
