568	                  </motion.div>
569	                ))}
570	              </motion.div>
571	            </AnimatePresence>
572	          )}
573	        </main>
574	
575	        {/* Carrinho desktop (sidebar) */}
576	        <CarrinhoDesktop carrinho={carrinho} onAdicionar={altCarrinho} onCheckout={irParaCheckout} />
577	      </div>
578	
579	      {/* ── Botão flutuante carrinho (mobile) ───────────────────────── */}
580	      <AnimatePresence>
581	        {totalItens > 0 && !carrinhoAberto && ap.aberto !== false && (
582	          <motion.div
583	            initial={{ y: 80, opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: 80, opacity: 0 }}
584	            className="fixed bottom-6 left-4 right-4 z-30 lg:hidden">
585	            <button onClick={() => setCarrinhoAberto(true)}
586	              className="w-full flex items-center justify-between bg-[#FF441F] hover:bg-[#E63A19] text-white rounded-2xl px-5 py-3.5 font-bold shadow-lg shadow-[#FF441F]/30 transition-colors">
587	              <span className="bg-[#E63A19] rounded-xl px-2.5 py-0.5 text-sm font-bold">{totalItens}</span>
588	              <span>Ver carrinho</span>
589	              <span className="text-white/80 text-sm">{fmt(totalValor)}</span>
590	            </button>
591	          </motion.div>
592	        )}
593	      </AnimatePresence>
594	
595	      {/* ── Drawer carrinho (mobile) ────────────────────────────────── */}
596	      <AnimatePresence>
597	        {carrinhoAberto && (
598	          <CarrinhoMobile
